import { createEntity, createProject, rewriteEntityReferences, validateProject } from './model';
import type { ProjectData, ProjectContent, Validity } from './types';
import type { PublicProjection } from './projection';
import { sha256, jsonBytes } from '../storage/json';

/** Internal UUIDs derive exclusively from public IDs, including independently approved citations. */
export async function portableRuntimeProject(projection:PublicProjection):Promise<{project:ProjectData;publicToRuntime:Record<string,string>}> {
 const contentHash=await sha256(jsonBytes(projection)),toUuid=(hash:string)=>`${hash.slice(0,8)}-${hash.slice(8,12)}-4${hash.slice(13,16)}-a${hash.slice(17,20)}-${hash.slice(20,32)}`,projectId=toUuid(contentHash),versions=projection.versions??[];
 if(versions.length>128||new Set(versions.map(pin=>pin.id)).size!==versions.length||versions.some(pin=>pin.projection.versions?.length))throw Error('EXPORT_UNSUPPORTED: 公開引用版の上限・重複・依存形式が不正です。');
 const editions=[projection,...versions.map(pin=>pin.projection)],ids=new Set(editions.flatMap(edition=>[...edition.entities.map(entity=>entity.id),...edition.relations.map(relation=>relation.id)]));versions.forEach(pin=>ids.add(pin.id));
 function embedded(value:unknown){if(Array.isArray(value)){value.forEach(embedded);return;}if(!value||typeof value!=='object')return;const object=value as Record<string,unknown>;if(typeof object.id==='string'&&typeof object.text==='string'&&typeof object.kind==='string')ids.add(object.id);if(typeof object.id==='string'&&typeof object.eventKey==='string')ids.add(object.id);Object.values(object).forEach(embedded);}
 editions.forEach(edition=>edition.entities.forEach(entity=>embedded(entity.data)));const mapping:Record<string,string>={'public-project':projectId};for(const id of ids)mapping[id]=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(id)?id:toUuid(await sha256(new TextEncoder().encode(`scenario-runtime-1:${id}`)));
 function native(value:unknown,versionId:string):unknown{if(Array.isArray(value))return value.map(item=>native(item,versionId));if(!value||typeof value!=='object')return value;const object=value as Record<string,unknown>,output=Object.fromEntries(Object.entries(object).map(([key,item])=>[key,['sourceVersionId','targetSnapshotId'].includes(key)&&item==='public-project'?versionId:native(item,versionId)]));if(typeof object.id==='string'&&ids.has(object.id))output.id=mapping[object.id];if(Array.isArray(object.links))output.links=object.links.map(raw=>{const link=raw as Record<string,unknown>;return {start:link.start,end:link.end,target:{entityId:link.targetId,...link.blockId?{blockId:link.blockId}:{},...link.lineId?{lineId:link.lineId}:{},...link.sourceVersionId?{sourceVersionId:link.sourceVersionId==='public-project'?versionId:link.sourceVersionId}:{},...link.targetStart!==undefined?{start:link.targetStart,end:link.targetEnd}:{}}};});return output;}
 function convert(edition:PublicProjection,versionId:string):ProjectData{
  const project=createProject(edition.title);project.projectId=projectId;project.mainStart=edition.mainStart??'0';project.calendars[0].id=project.calendarId='public-calendar-default';const fixedAt='1970-01-01T00:00:00.000Z';
  project.entities=edition.entities.map(publicEntity=>{const data=native(publicEntity.data,versionId)as Record<string,unknown>;delete data.bytesIncluded;const entity=createEntity(projectId,publicEntity.kind,publicEntity.name,data as any);entity.id=mapping[publicEntity.id];entity.createdAt=entity.updatedAt=fixedAt;entity.status='confirmed';return rewriteEntityReferences(entity,mapping);});
  project.views=[];project.relations=edition.relations.map(relation=>({...relation,id:mapping[relation.id],projectId,fromId:mapping[relation.fromId],toId:mapping[relation.toId],evidenceIds:relation.evidenceIds.map(id=>mapping[id]),revision:'0',status:'confirmed' as const,visibility:'projection' as const,validity:rewriteEntityReferences(createEntity(projectId,'assertion','公開関係の期間',{subjectId:mapping[relation.fromId],predicate:'relation',validity:(native(relation.validity,versionId)as Validity|undefined)??{worldRange:null,routeCondition:null,presentationAnchor:null}}),mapping).data.validity!}));project.worldReferences=[];project.snapshots=[];project.history=[];
  if(edition.calendars.length){const defaults=project.calendars[0];project.calendars=edition.calendars.map(calendar=>calendar.kind==='repeating'?{id:calendar.id,name:calendar.name,kind:'repeating',originLabel:calendar.originLabel,ticksPerDay:calendar.ticksPerDay,years:calendar.years??[]}:{...defaults,id:calendar.id,name:calendar.name,kind:'gregorian',ticksPerDay:calendar.ticksPerDay});project.calendarId=project.calendars[0].id;}
  return project;
 }
 const project=convert(projection,projectId);
 for(const pin of versions){const {history:_history,snapshots:_snapshots,authorAlternatives:_alternatives,...content}=convert(pin.projection,mapping[pin.id]);project.snapshots.push({id:mapping[pin.id],versionLabel:pin.projection.title,createdAt:'1970-01-01T00:00:00.000Z',content:content as ProjectContent,contentHash:await sha256(jsonBytes(content))});}
 const checked=validateProject(project);if(!checked.ok)throw Object.assign(new Error('EXPORT_UNSUPPORTED: 公開実行内容を同じstrict契約へ対応できません。'),{issues:checked.issues});return {project,publicToRuntime:mapping};
}
